from decimal import Decimal
from typing import Any


def _value(source: dict | None, key: str) -> Any:
    if not source:
        return ""
    return source.get(key, "")


def _text(value: Any) -> str:
    if value is None:
        return ""
    return str(value)


def _length(value: Any) -> int:
    return len(_text(value))


def _numeric(value: Any) -> Decimal:
    if value is None or value == "":
        return Decimal(0)
    return Decimal(str(value))


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    errors: list[dict] = []

    if event in ("INSERT", "UPDATE"):
        if _length(_value(record, "ACCT_NM")) < 2:
            errors.append(
                {
                    "code": "E1001",
                    "message": "Account name too short",
                    "severity": "BLOCK",
                }
            )

        account_type = _value(record, "ACCT_TYP")
        if not (
            account_type == "C"
            or account_type == "P"
            or account_type == "R"
            or account_type == "X"
        ):
            errors.append(
                {
                    "code": "E1002",
                    "message": "Invalid account type",
                    "severity": "BLOCK",
                }
            )

        if _numeric(_value(record, "ANN_REV")) < Decimal(0):
            errors.append(
                {
                    "code": "E1003",
                    "message": "Annual revenue negative",
                    "severity": "BLOCK",
                }
            )

        if _length(_value(record, "REGION_CD")) != 3:
            errors.append(
                {
                    "code": "E1005",
                    "message": "Region code must be 3 chars",
                    "severity": "WARN",
                }
            )

    if event == "UPDATE":
        old_hold = _value(old, "CRED_HOLD")
        new_hold = _value(record, "CRED_HOLD")
        credit_limit = _numeric(_value(record, "CRED_LIMIT"))

        if old_hold == "Y" and new_hold == "N" and credit_limit <= Decimal(0):
            errors.append(
                {
                    "code": "E1004",
                    "message": "Cannot release credit hold with zero credit limit",
                    "severity": "BLOCK",
                }
            )

    return errors


def is_blocked(errors: list[dict]) -> bool:
    return any(error.get("severity") == "BLOCK" for error in errors)
